solution:
def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def decimal_to_base(num: int, base: int) -> str:
    if num == 0:
        return '0'
    digits = '0123456789ABCDEF'
    result = ''
    while num > 0:
        result = digits[num % base] + result
        num //= base
    return result

def round_to_places(num: float, places: int) -> float:
    import math
    multiplier = 10 ** places
    shifted = num * multiplier
    if shifted >= 0:
        rounded = math.floor(shifted + 0.5)
    else:
        rounded = math.ceil(shifted - 0.5)
    return rounded / multiplier

def find_divisors(n: int) -> list:
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return sorted(divisors)

def nth_prime(n: int) -> int:
    if n == 1:
        return 2
    count = 1
    candidate = 3
    while count < n:
        is_prime = True
        if candidate % 2 == 0:
            is_prime = False
        else:
            i = 3
            while i * i <= candidate:
                if candidate % i == 0:
                    is_prime = False
                    break
                i += 2
        if is_prime:
            count += 1
        if count == n:
            return candidate
        candidate += 2
    return -1

def busca_binaria(arr: list[int], alvo: int) -> int:
    esquerda, direita = 0, len(arr) - 1
    while esquerda <= direita:
        meio = (esquerda + direita) // 2
        if arr[meio] == alvo:
            return meio
        elif arr[meio] < alvo:
            esquerda = meio + 1
        else:
            direita = meio - 1
    return -1

def par_com_soma(arr: list[int], alvo: int) -> bool:
    esquerda, direita = 0, len(arr) - 1
    while esquerda < direita:
        soma = arr[esquerda] + arr[direita]
        if soma == alvo:
            return True
        elif soma < alvo:
            esquerda += 1
        else:
            direita -= 1
    return False

def busca_rotacionado(nums: list[int], alvo: int) -> int:
    esquerda, direita = 0, len(nums) - 1
    while esquerda <= direita:
        meio = (esquerda + direita) // 2
        if nums[meio] == alvo:
            return meio
        # lado esquerdo ordenado?
        if nums[esquerda] <= nums[meio]:
            if nums[esquerda] <= alvo < nums[meio]:
                direita = meio - 1
            else:
                esquerda = meio + 1
        else:
            if nums[meio] < alvo <= nums[direita]:
                esquerda = meio + 1
            else:
                direita = meio - 1
    return -1

def maior_substring_sem_repeticao(s: str) -> int:
    ultimo_indice = {}
    esquerda = 0
    max_len = 0
    for direita, char in enumerate(s):
        if char in ultimo_indice and ultimo_indice[char] >= esquerda:
            esquerda = ultimo_indice[char] + 1
        ultimo_indice[char] = direita
        max_len = max(max_len, direita - esquerda + 1)
    return max_len

def factorial(n: int) -> int:
    if n == 0:
        return 1
    return n * factorial(n-1)

def fibonacci(n: int) -> int:
    memo = {0: 0, 1: 1}
    def fib(k):
        if k not in memo:
            memo[k] = fib(k-1) + fib(k-2)
        return memo[k]
    return fib(n)

def contar_palavras(texto: str) -> int:
    """Retorna o número de palavras em uma string.
    Palavras são sequências de caracteres separadas por um ou mais espaços.
    Exemplo: contar_palavras('Olá mundo') -> 2
    """
    return len(texto.split())

def contar_formas_escada(n: int) -> int:
    memo = {0: 1, 1: 1, 2: 2}
    def f(k):
        if k not in memo:
            memo[k] = f(k-1) + f(k-2) + f(k-3)
        return memo[k]
    return f(n)

def validar_email(email: str) -> bool:
    """Verifica se o email é válido (formato simples: algo@algo.algo).
    Não permite espaços, deve ter exatamente um @, e o domínio deve ter pelo menos um ponto.
    Exemplo: validar_email('teste@exemplo.com') -> True
    """
    if ' ' in email:
        return False
    partes = email.split('@')
    if len(partes) != 2:
        return False
    local, dominio = partes
    if not local or not dominio:
        return False
    if '.' not in dominio:
        return False
    return True

def tamanho_sec_lis(arr: list[int]) -> int:
    n = len(arr)
    memo = {}
    def f(i, prev_idx):
        if i == n:
            return 0
        key = (i, prev_idx)
        if key not in memo:
            incluir = 0
            if prev_idx == -1 or arr[i] > arr[prev_idx]:
                incluir = 1 + f(i+1, i)
            excluir = f(i+1, prev_idx)
            memo[key] = max(incluir, excluir)
        return memo[key]
    return f(0, -1)

def distancia_edicao(s1: str, s2: str) -> int:
    m, n = len(s1), len(s2)
    memo = {}
    def f(i, j):
        if i == m:
            return n - j
        if j == n:
            return m - i
        key = (i, j)
        if key not in memo:
            if s1[i] == s2[j]:
                memo[key] = f(i+1, j+1)
            else:
                memo[key] = 1 + min(
                    f(i+1, j),   # deletar
                    f(i, j+1),   # inserir
                    f(i+1, j+1)  # substituir
                )
        return memo[key]
    return f(0, 0)

