def transpor_matriz(matriz: list) -> list:
    if not matriz or not matriz[0]:
        return []
    linhas = len(matriz)
    colunas = len(matriz[0])
    return [[matriz[i][j] for i in range(linhas)] for j in range(colunas)]

def snake_to_camel(s: str) -> str:
    if not s:
        return s
    parts = s.split('_')
    return parts[0] + ''.join(p.capitalize() for p in parts[1:])

def camel_to_snake(s: str) -> str:
    if not s:
        return s
    result = []
    for ch in s:
        if ch.isupper():
            result.append('_')
            result.append(ch.lower())
        else:
            result.append(ch)
    return ''.join(result).lstrip('_')

def roman_to_int(s: str) -> int:
    roman_map = {'I':1, 'V':5, 'X':10, 'L':50, 'C':100, 'D':500, 'M':1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        val = roman_map[ch]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val
    return total

def int_to_roman(num: int) -> str:
    values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    symbols = ['M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I']
    result = []
    for v, s in zip(values, symbols):
        while num >= v:
            result.append(s)
            num -= v
    return ''.join(result)

def bytes_to_readable(size: int) -> str:
    if size < 0:
        size = 0
    if size == 0:
        return '0 B'
    units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB']
    i = 0
    while size >= 1024 and i < len(units)-1:
        size /= 1024.0
        i += 1
    return f'{size:.1f} {units[i]}'

def readable_to_bytes(s: str) -> int:
    import re
    match = re.match(r'^(\d+\.?\d*)\s*(B|KB|MB|GB|TB|PB)$', s.strip())
    if not match:
        raise ValueError('Formato inválido')
    value = float(match.group(1))
    unit = match.group(2)
    units = {'B': 1, 'KB': 1024, 'MB': 1024**2, 'GB': 1024**3, 'TB': 1024**4, 'PB': 1024**5}
    return int(value * units[unit])

def eh_primo(n: int) -> bool:
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def primos_entre(inicio: int, fim: int) -> list:
    def eh_primo(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True
    return [n for n in range(inicio, fim + 1) if eh_primo(n)]

def decimal_para_base(n: int, base: int) -> str:
    if n == 0:
        return '0'
    digitos = '0123456789ABCDEF'
    resultado = ''
    while n > 0:
        resultado = digitos[n % base] + resultado
        n //= base
    return resultado

def teto_sem_math(x: float) -> int:
    if x == int(x):
        return int(x)
    if x > 0:
        return int(x) + 1
    else:
        return int(x)

def divisores_comuns(a: int, b: int) -> list:
    if a <= 0 or b <= 0:
        return []
    m = min(a, b)
    divisores = []
    for i in range(1, m + 1):
        if a % i == 0 and b % i == 0:
            divisores.append(i)
    return divisores

