def maior_frequencia(lista: list) -> tuple:
    from collections import Counter
    if not lista:
        return (None, 0)
    contagem = Counter(lista)
    max_freq = max(contagem.values())
    candidatos = [elem for elem, freq in contagem.items() if freq == max_freq]
