    """Soma os dígitos de um número inteiro não negativo recursivamente.
    Exemplo: soma_digitos(1234) -> 10"""

solution:
def soma_digitos(n: int) -> int:
    if n == 0:
        return 0
    return n % 10 + soma_digitos(n // 10)

def maior_substring_palindromo(s: str) -> str:
    n = len(s)
    if n < 2:
        return s
    dp = [[False] * n for _ in range(n)]
    inicio = 0
    max_len = 1
    for i in range(n):
        dp[i][i] = True
    for i in range(n-1):
        if s[i] == s[i+1]:
            dp[i][i+1] = True
            inicio = i
            max_len = 2
    for comprimento in range(3, n+1):
        for i in range(n - comprimento + 1):
            j = i + comprimento - 1
            if s[i] == s[j] and dp[i+1][j-1]:
                dp[i][j] = True
                if comprimento > max_len:
                    inicio = i
                    max_len = comprimento
    return s[inicio:inicio+max_len]

def combinacoes_soma(alvo: int, nums: list[int]) -> list[list[int]]:
    from functools import lru_cache
    nums = sorted(nums)
    @lru_cache(maxsize=None)
    def dfs(restante, idx):
        if restante == 0:
            return [[]]
        if restante < 0 or idx >= len(nums):
            return []
        resultados = []
        # pular o número atual
        resultados.extend(dfs(restante, idx+1))
        # usar o número atual (pode repetir)
        for comb in dfs(restante - nums[idx], idx):
            resultados.append([nums[idx]] + comb)
        return resultados
    return dfs(alvo, 0)

def minimo_caminho(grid: list[list[int]]) -> int:
    from functools import lru_cache
    m, n = len(grid), len(grid[0])
    @lru_cache(maxsize=None)
    def dfs(i, j):
        if i == m-1 and j == n-1:
            return grid[i][j]
        if i >= m or j >= n:
            return float('inf')
        direita = dfs(i, j+1)
        baixo = dfs(i+1, j)
        return grid[i][j] + min(direita, baixo)
    return dfs(0, 0)

def flatten_list(lista_aninhada: list) -> list:
    resultado = []
    for item in lista_aninhada:
        if isinstance(item, list):
            resultado.extend(flatten_list(item))
        else:
            resultado.append(item)
    return resultado

def flatten_and_sort(lista_aninhada: list) -> list:
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item
    return sorted(flatten(lista_aninhada))

from functools import lru_cache

def fibonacci_memo(n: int) -> int:
    @lru_cache(maxsize=None)
    def fib(k: int) -> int:
        if k < 2:
            return k
        return fib(k - 1) + fib(k - 2)
    return fib(n)

def soma_lista_rec(lista: list) -> int:
    if not lista:
        return 0
    return lista[0] + soma_lista_rec(lista[1:])

def contagem_regressiva(n: int) -> list:
    if n < 0:
        return []
    if n == 0:
        return [0]
    return [n] + contagem_regressiva(n - 1)

from functools import lru_cache

def combinacoes_mochila(itens: list, capacidade: int) -> int:
    @lru_cache(maxsize=None)
    def dfs(i: int, restante: int) -> int:
        if restante == 0:
            return 1
        if i == len(itens) or restante < 0:
            return 0
        return dfs(i + 1, restante) + dfs(i + 1, restante - itens[i])
    return dfs(0, capacidade)

