def validate_phone(phone: str) -> bool:
    import re
    return bool(re.fullmatch(r'\(\d{2}\) \d{4,5}-?\d{4}', phone))

def validate_license_plate(plate: str) -> bool:
    import re
    old = re.fullmatch(r'[A-Z]{3}-\d{4}', plate)
    mercosul = re.fullmatch(r'[A-Z]{3}\d[A-Z]\d{2}', plate)
    return bool(old or mercosul)

def binary_search(arr: list[int], target: int) -> int:
    esq, dir = 0, len(arr) - 1
    while esq <= dir:
        meio = (esq + dir) // 2
        if arr[meio] == target:
            return meio
        elif arr[meio] < target:
            esq = meio + 1
        else:
            dir = meio - 1
    return -1

def first_occurrence(arr: list[int], target: int) -> int:
    esq, dir = 0, len(arr) - 1
    resultado = -1
    while esq <= dir:
        meio = (esq + dir) // 2
        if arr[meio] == target:
            resultado = meio
            dir = meio - 1
        elif arr[meio] < target:
            esq = meio + 1
        else:
            dir = meio - 1
    return resultado

def two_sum_sorted(nums: list[int], target: int) -> tuple[int, int] | None:
    i, j = 0, len(nums) - 1
    while i < j:
        soma = nums[i] + nums[j]
        if soma == target:
            return (i, j)
        elif soma < target:
            i += 1
        else:
            j -= 1
    return None

def move_zeros(nums: list[int]) -> list[int]:
    res = []
    zeros = 0
    for num in nums:
        if num != 0:
            res.append(num)
        else:
            zeros += 1
    res.extend([0] * zeros)
    return res

def max_subarray_sum(nums: list[int], k: int) -> int:
    if k > len(nums):
        return 0
    soma_atual = sum(nums[:k])
    max_soma = soma_atual
    for i in range(k, len(nums)):
        soma_atual += nums[i] - nums[i - k]
        max_soma = max(max_soma, soma_atual)
    return max_soma

def human_readable_bytes(n: int) -> str:
    if n < 1024:
        return f'{n} B'
    units = ['KiB', 'MiB', 'GiB', 'TiB']
    val = float(n)
    for unit in units:
        val /= 1024.0
        if val < 1024.0:
            return f'{val:.2f} {unit}'
    return f'{val:.2f} PiB'  # beyond TiB, but not required

def snake_to_camel(s: str) -> str:
    if not s:
        return s
    parts = s.split('_')
    return parts[0] + ''.join(p.capitalize() for p in parts[1:])

def convert_keys_snake_to_camel(d: dict) -> dict:
    if not isinstance(d, dict):
        return d
    new_dict = {}
    for key, value in d.items():
        new_key = snake_to_camel(key)
        if isinstance(value, dict):
            new_value = convert_keys_snake_to_camel(value)
        elif isinstance(value, list):
            new_value = [convert_keys_snake_to_camel(item) if isinstance(item, dict) else item for item in value]
        else:
            new_value = value
        new_dict[new_key] = new_value
    return new_dict

prompt:
def group_and_sum(transactions: list, group_key: str, sum_key: str) -> dict:
    """Agrupa uma lista de dicionários por uma chave e soma os valores de outra chave em cada grupo.
    Exemplo: group_and_sum([{'cat':'A','val':10},{'cat':'B','val':20},{'cat':'A','val':5}], 'cat', 'val') -> {'A':15, 'B':20}
    """

solution:
def group_and_sum(transactions: list, group_key: str, sum_key: str) -> dict:
    result = {}
    for t in transactions:
        g = t[group_key]
        v = t.get(sum_key, 0)
        result[g] = result.get(g, 0) + v
    return result

