    Exemplo: min_window_substring('ADOBECODEBANC', 'ABC') -> 'BANC'"""

solution:
def min_window_substring(s: str, t: str) -> str:
    from collections import Counter
    if not s or not t:
        return ''
    dict_t = Counter(t)
    janela = {}
    esquerda = 0
    formado = 0
    necessario = len(dict_t)
    min_len = float('inf')
    inicio = 0
    for direita in range(len(s)):
        char = s[direita]
        janela[char] = janela.get(char, 0) + 1
        if char in dict_t and janela[char] == dict_t[char]:
            formado += 1
        while formado == necessario:
            if direita - esquerda + 1 < min_len:
                min_len = direita - esquerda + 1
                inicio = esquerda
            char_esq = s[esquerda]
            janela[char_esq] -= 1
            if char_esq in dict_t and janela[char_esq] < dict_t[char_esq]:
                formado -= 1
            esquerda += 1
    return s[inicio:inicio + min_len] if min_len != float('inf') else ''

