    """Retorna a quantidade de divisores positivos de n.
    Exemplo: contar_divisores(12) -> 6 (divisores: 1,2,3,4,6,12)."""

solution:
def contar_divisores(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            count += 1
            if i * i != n:
                count += 1
        i += 1
    return count

