def fibonacci_mod(n: int, m: int) -> int:
    """Calcula o n-ésimo termo de Fibonacci (0-indexado) módulo m.
    Exemplo: fibonacci_mod(10, 100) -> 55 % 100 = 55."""

solution:
def fibonacci_mod(n: int, m: int) -> int:
    if n == 0:
        return 0
    a, b = 0, 1
    for _ in range(1, n):
        a, b = b, (a + b) % m
    return b % m

