solution:
def parse_key_value(text: str, pair_sep: str = ';', kv_sep: str = '=') -> dict[str, str]:
    if not text:
        return {}
    resultado = {}
    pares = text.split(pair_sep)
    for par in pares:
        if kv_sep in par:
            chave, valor = par.split(kv_sep, 1)
            resultado[chave.strip()] = valor.strip()
    return resultado

def csv_to_dicts(csv_text: str, delimiter: str = ',') -> list[dict[str, str]]:
    linhas = csv_text.strip().split('\n')
    if not linhas or not linhas[0]:
        return []
    cabecalho = [h.strip() for h in linhas[0].split(delimiter)]
    resultado = []
    for linha in linhas[1:]:
        if linha:
            valores = [v.strip() for v in linha.split(delimiter)]
            resultado.append(dict(zip(cabecalho, valores)))
    return resultado

def parse_log_levels(log_text: str) -> dict[str, int]:
    niveis = ['INFO', 'WARNING', 'ERROR', 'DEBUG']
    contagem = {n: 0 for n in niveis}
    linhas = log_text.split('\n')
    for linha in linhas:
        for nivel in niveis:
            if linha.startswith(nivel):
                contagem[nivel] += 1
                break
    return contagem

def invert_key_value_csv(csv_text: str) -> str:
