def valida_placa(placa: str) -> bool:
    import re
    placa = placa.upper().replace('-', '')
    padrao_antigo = r'^[A-Z]{3}\d{4}$'
    padrao_mercosul = r'^[A-Z]{3}\d[A-Z]\d{2}$'
    return bool(re.match(padrao_antigo, placa)) or bool(re.match(padrao_mercosul, placa))

def soma_recursiva(n: int) -> int:
    if n == 0:
        return 0
    return n + soma_recursiva(n - 1)

def troco_minimo(moedas: list, valor: int) -> int:
    memo = {0: 0}
    def dp(v):
        if v in memo:
            return memo[v]
        menor = float('inf')
        for m in moedas:
            if m <= v:
                menor = min(menor, 1 + dp(v - m))
        memo[v] = menor
        return memo[v]
    return dp(valor)

def pascal_linha(n: int) -> list:
    if n == 0:
        return [1]
    anterior = pascal_linha(n-1)
    linha = [1]
    for i in range(1, len(anterior)):
        linha.append(anterior[i-1] + anterior[i])
    linha.append(1)
    return linha

def maior_subsequencia_crescente(seq: list) -> int:
    if not seq:
        return 0
    memo = {}
    def dp(i):
        if i in memo:
            return memo[i]
        max_len = 1
        for j in range(i):
            if seq[j] < seq[i]:
                max_len = max(max_len, 1 + dp(j))
        memo[i] = max_len
        return max_len
    return max(dp(i) for i in range(len(seq)))

def parse_csv(csv_str: str) -> list[dict]:
    linhas = csv_str.strip().split('\n')
    if not linhas or linhas[0] == '':
        return []
    cabecalho = linhas[0].split(',')
    resultado = []
    for linha in linhas[1:]:
        if linha == '':
            continue
        valores = linha.split(',')
        dicionario = {}
        for i, chave in enumerate(cabecalho):
            dicionario[chave] = valores[i] if i < len(valores) else ''
        resultado.append(dicionario)
    return resultado

def parse_apache_log(line: str) -> dict:
    import re
    pattern = r'^(\S+) (\S+) (\S+) \[(.+?)\] "(.+?)" (\d+) (\d+)$'
    match = re.match(pattern, line)
    if not match:
        return {}
    return {
        'ip': match.group(1),
        'ident': match.group(2),
        'user': match.group(3),
        'datetime': match.group(4),
        'request': match.group(5),
        'status': match.group(6),
        'size': match.group(7)
