def parse_csv_quoted(csv_str: str) -> list[list[str]]:
    if not csv_str:
        return []
    linhas = csv_str.split('\n')
    resultado = []
    for linha in linhas:
        if linha == '':
            continue
        campos = []
        campo_atual = ''
        dentro_aspas = False
        for char in linha:
            if char == '"' and not dentro_aspas:
                dentro_aspas = True
            elif char == '"' and dentro_aspas:
                dentro_aspas = False
            elif char == ',' and not dentro_aspas:
                campos.append(campo_atual)
                campo_atual = ''
            else:
                campo_atual += char
        campos.append(campo_atual)
        resultado.append(campos)
    return resultado

