        return {}
    linhas = text.split('\n')
    resultado = {}
    for linha in linhas:
        if not linha.strip():
            continue
        if '=' not in linha:
            continue
        chave, valor = linha.split('=', 1)
        resultado[chave.strip()] = valor.strip()
