def human_to_bytes(s: str) -> int:
    """Converte uma string legível de tamanho (ex: '1.5 MB') em bytes.
    Exemplo: human_to_bytes('1.5 MB') -> 1572864
    """
    import re
    match = re.match(r'^([\d.]+)\s*([A-Z]+)$', s.strip())
    if not match:
        raise ValueError('Invalid format')
    num = float(match.group(1))
    unit = match.group(2)
    units = {'B':1, 'KB':1024, 'MB':1024**2, 'GB':1024**3, 'TB':1024**4, 'PB':1024**5}
    if unit not in units:
        raise ValueError('Unknown unit')
    return int(num * units[unit])

def parse_custom_log(log_line: str) -> dict:
    import re
    match = re.match(r'^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+): (.+)$', log_line)
    if not match:
        return {}
    return {
        'timestamp': match.group(1),
        'level': match.group(2),
        'message': match.group(3)
    }

