solution:
def longest_substring_without_repeating(s: str) -> int:
    ultimo_indice = {}
    esquerda = 0
    max_len = 0
    for direita, char in enumerate(s):
        if char in ultimo_indice and ultimo_indice[char] >= esquerda:
            esquerda = ultimo_indice[char] + 1
        ultimo_indice[char] = direita
        max_len = max(max_len, direita - esquerda + 1)
    return max_len

from functools import lru_cache

def combinacao(n: int, k: int) -> int:
    @lru_cache(maxsize=None)
    def comb(n: int, k: int) -> int:
        if k == 0 or k == n:
            return 1
        return comb(n - 1, k - 1) + comb(n - 1, k)
    return comb(n, k)

def subsequencia_crescente_maxima(seq: list[int]) -> int:
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i: int) -> int:
        if i >= len(seq):
            return 0
        melhor = 1
        for j in range(i + 1, len(seq)):
            if seq[j] > seq[i]:
                melhor = max(melhor, 1 + dp(j))
        return melhor

    if not seq:
        return 0
    return max(dp(i) for i in range(len(seq)))

def subsequencia_palindromo_mais_longa(s: str) -> int:
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def lps(i: int, j: int) -> int:
        if i > j:
            return 0
        if i == j:
            return 1
        if s[i] == s[j]:
            return 2 + lps(i + 1, j - 1)
        return max(lps(i + 1, j), lps(i, j - 1))

    return lps(0, len(s) - 1) if s else 0

def conta_duplicatas(lista: list) -> int:
