    contagens = Counter(lista)
    return sum(1 for c in contagens.values() if c > 1)

def intersecao_multiplos(conjuntos: list[set]) -> set:
    if not conjuntos:
        return set()
    resultado = conjuntos[0].copy()
    for s in conjuntos[1:]:
        resultado &= s
        if not resultado:
            break
    return resultado

def elementos_comuns_listas(listas: list[list]) -> set:
    if not listas:
        return set()
    resultado = set(listas[0])
    for lst in listas[1:]:
        resultado &= set(lst)
        if not resultado:
            break
    return resultado

