def rotacionar_90(matriz: list[list[int]]) -> list[list[int]]:
    if not matriz:
        return []
    n_linhas = len(matriz)
    n_cols = len(matriz[0])
    return [[matriz[n_linhas - 1 - j][i] for j in range(n_linhas)] for i in range(n_cols)]

def espiral_matriz(matriz: list[list[int]]) -> list[int]:
    if not matriz:
        return []
    resultado = []
    topo, baixo, esquerda, direita = 0, len(matriz)-1, 0, len(matriz[0])-1
    while topo <= baixo and esquerda <= direita:
        for j in range(esquerda, direita+1):
            resultado.append(matriz[topo][j])
        topo += 1
        for i in range(topo, baixo+1):
            resultado.append(matriz[i][direita])
        direita -= 1
        if topo <= baixo:
            for j in range(direita, esquerda-1, -1):
                resultado.append(matriz[baixo][j])
            baixo -= 1
        if esquerda <= direita:
            for i in range(baixo, topo-1, -1):
                resultado.append(matriz[i][esquerda])
            esquerda += 1
    return resultado

