def inverter_palavras(frase: str) -> str:
    if not frase:
        return ""
    palavras = frase.split()
    invertidas = palavras[::-1]
    if invertidas:
        invertidas[0] = invertidas[0].capitalize()
        invertidas[-1] = invertidas[-1].lower() if len(invertidas) > 1 else invertidas[0]
        # Corrigir capitalização: primeira maiúscula, demais minúsculas
        resultado = []
        for i, p in enumerate(invertidas):
            if i == 0:
                resultado.append(p.capitalize())
            else:
                resultado.append(p.lower())
        return " ".join(resultado)
    return ""

def converter_para_base(n: int, base: int) -> str:
    if n == 0:
        return '0'
    digitos = '0123456789ABCDEF'
    resultado = ''
    while n > 0:
        resultado = digitos[n % base] + resultado
        n //= base
    return resultado

def soma_numeros_amigaveis(limite: int) -> int:
    def soma_divisores_proprios(n):
        if n < 2:
            return 0
        soma = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                soma += i
                if i != n // i:
                    soma += n // i
        return soma

    amigaveis = set()
    for a in range(2, limite):
        b = soma_divisores_proprios(a)
        if b > a and b < limite and soma_divisores_proprios(b) == a:
            amigaveis.add(a)
            amigaveis.add(b)
    return sum(amigaveis)

def contar_ocorrencias_por_categoria(lista: list[dict], chave_categoria: str, chave_valor: str) -> dict:
    contagem = {}
    for dicionario in lista:
        categoria = dicionario[chave_categoria]
        if categoria not in contagem:
            contagem[categoria] = 0
        contagem[categoria] += 1
    return contagem

def encontrar_par_menor_distancia(arr: list[int]) -> tuple[int, int]:
    if len(arr) < 2:
        return (-1, -1)
    min_diff = float('inf')
    par = (-1, -1)
    for i in range(len(arr) - 1):
        diff = abs(arr[i+1] - arr[i])
        if diff < min_diff:
            min_diff = diff
            par = (i, i+1)
    return par

def contagem_subarrays_palindromos(s: str) -> int:
    def expandir_centro(esq: int, dir: int) -> int:
        cont = 0
        while esq >= 0 and dir < len(s) and s[esq] == s[dir]:
            cont += 1
            esq -= 1
            dir += 1
        return cont
    total = 0
    for i in range(len(s)):
        total += expandir_centro(i, i)  # ímpares
        total += expandir_centro(i, i+1)  # pares
    return total

def janela_deslizante_sem_repeticao(s: str) -> int:
    ultimo_indice = {}
    esq = 0
    max_len = 0
    for dir, ch in enumerate(s):
        if ch in ultimo_indice and ultimo_indice[ch] >= esq:
            esq = ultimo_indice[ch] + 1
        ultimo_indice[ch] = dir
        max_len = max(max_len, dir - esq + 1)
    return max_len

def pow_recursive(base: int, exp: int) -> int:
    if exp == 0:
        return 1
    return base * pow_recursive(base, exp - 1)

def fatorial_recursivo(n: int) -> int:
    if n <= 1:
        return 1
    return n * fatorial_recursivo(n - 1)

def palindromo_recursivo(s: str) -> bool:
    s = s.replace(" ", "").lower()
    if len(s) <= 1:
        return True
    if s[0] != s[-1]:
        return False
    return palindromo_recursivo(s[1:-1])

def combinacao_memo(n: int, k: int, memo: dict = {}) -> int:
    if k == 0 or k == n:
        return 1
    if (n, k) in memo:
        return memo[(n, k)]
    memo[(n, k)] = combinacao_memo(n - 1, k - 1, memo) + combinacao_memo(n - 1, k, memo)
    return memo[(n, k)]

def transpose_matrix(mat: list[list[int]]) -> list[list[int]]:
    if not mat:
        return []
    return [[mat[j][i] for j in range(len(mat))] for i in range(len(mat[0]))]

def is_symmetric(mat: list[list[int]]) -> bool:
    n = len(mat)
    for i in range(n):
        for j in range(i, n):
            if mat[i][j] != mat[j][i]:
                return False
    return True

def rotate_clockwise(mat: list[list[int]]) -> list[list[int]]:
    if not mat:
        return []
    return [list(row) for row in zip(*mat[::-1])]

def rotate_counterclockwise(mat: list[list[int]]) -> list[list[int]]:
    if not mat:
        return []
    return [list(row) for row in reversed(list(zip(*mat)))]

def add_matrices(mat1: list[list[int]], mat2: list[list[int]]) -> list[list[int]]:
    if not mat1:
        return []
    return [[mat1[i][j] + mat2[i][j] for j in range(len(mat1[0]))] for i in range(len(mat1))]

