solution:
def quociente_resto(dividendo: int, divisor: int) -> tuple:
    if divisor == 0:
        raise ValueError("Divisor não pode ser zero")
    quociente = dividendo // divisor
    resto = dividendo % divisor
    # Ajuste para garantir que resto seja não-negativo conforme convenção
    # Na verdade, Python já usa divisão euclidiana, então está correto
    return (quociente, resto)

