    """Recebe um CPF válido (11 dígitos) e retorna dicionário com 'valido' (bool), 'digitos_verificadores' (str dos dois últimos dígitos) e 'sequencia_repetida' (bool). Se inválido, retorna {'valido': False}.
    Exemplo: extrair_info_cpf('52998224725') -> {'valido': True, 'digitos_verificadores': '25', 'sequencia_repetida': False}"""

solution:
def extrair_info_cpf(cpf: str) -> dict:
    if not cpf.isdigit() or len(cpf) != 11:
        return {'valido': False}
    if cpf == cpf[0] * 11:
        return {'valido': False}
    def digito(ds):
        s = sum(int(cpf[i]) * (len(ds) + 1 - i) for i in range(len(ds)))
        r = 11 - (s % 11)
        return r if r < 10 else 0
    if digito(range(9)) == int(cpf[9]) and digito(range(10)) == int(cpf[10]):
        return {'valido': True, 'digitos_verificadores': cpf[9:11], 'sequencia_repetida': False}
    return {'valido': False}

