    memo = {}
    def comb(n, k):
        if k == 0 or k == n:
            return 1
        if (n, k) not in memo:
            memo[(n, k)] = comb(n-1, k-1) + comb(n-1, k)
        return memo[(n, k)]
    return comb(n, k)

def troco_minimo_moedas(moedas: list, valor: int) -> int:
