    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        esquerda, direita = i + 1, n - 1
        while esquerda < direita:
            soma = nums[i] + nums[esquerda] + nums[direita]
            if soma == 0:
