    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    # converte para decimal
    dec = 0
    for ch in value.upper():
        dec = dec * from_base + digits.index(ch)
    if dec == 0:
        return '0'
    # converte de decimal para nova base
    res = []
    while dec > 0:
