    import math
    multiplier = 10 ** decimals
    abs_num = abs(num * multiplier)
    fraction = abs_num - math.floor(abs_num)
    if fraction < 0.5:
        rounded = math.floor(abs_num)
    else:
        rounded = math.ceil(abs_num)
    result = rounded / multiplier
    return math.copysign(result, num)

