    while d * d <= n:
        count = 0
        while n % d == 0:
            n //= d
            count += 1
        if count > 0:
            factors.append((d, count))
        d += 1 if d == 2 else 2  # após 2 testa só ímpares
    if n > 1:
        factors.append((n, 1))
    return factors

