    @lru_cache(maxsize=None)
    def dp(n: int, max_parte: int) -> int:
        if n == 0:
            return 1
        if n < 0 or max_parte == 0:
            return 0
        return dp(n - max_parte, max_parte) + dp(n, max_parte - 1)
    return dp(n, max_parte)

