def contagem_palavras(texto: str) -> dict:
    import re
    palavras = re.findall(r'\w+', texto.lower())
    frequencia = {}
    for palavra in palavras:
        frequencia[palavra] = frequencia.get(palavra, 0) + 1
    return frequencia

def gcd(a, b) -> int:
    while b:
        a, b = b, a % b
    return a

def prime_factors(n) -> list:
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors.append(n)
    return factors

def to_base(n, base) -> str:
    if n == 0:
        return '0'
    digits = '0123456789ABCDEF'
    result = []
    while n > 0:
        result.append(digits[n % base])
        n //= base
    return ''.join(reversed(result))

def round_half_up(num, decimals) -> float:
    factor = 10 ** decimals
    if num >= 0:
        return int(num * factor + 0.5) / factor
    else:
        return int(num * factor - 0.5) / factor

def encontrar_palavra_mais_longa(frase: str) -> str:
    import re
    palavras = re.findall(r'\b\w+\b', frase)
    if not palavras:
        return ''
    return max(palavras, key=len)

def encontrar_triangulo(lados: list) -> bool:
    lados.sort()
    for i in range(len(lados) - 2):
        if lados[i] + lados[i+1] > lados[i+2]:
            return True
    return False

def contar_ocorrencias_por_chave(lista_dicts: list[dict], chave: str) -> dict:
    contagem = {}
    for d in lista_dicts:
        valor = d[chave]
        if valor in contagem:
            contagem[valor] += 1
        else:
            contagem[valor] = 1
    return contagem

def combinar_dicionarios_por_chave(lista_dicts: list[dict], chave_agrupadora: str, chave_valor: str) -> dict:
    resultado = {}
    for d in lista_dicts:
        chave = d[chave_agrupadora]
        valor = d[chave_valor]
        if chave not in resultado:
            resultado[chave] = []
        resultado[chave].append(valor)
    return resultado

def valida_dados_brasileiros(dado: str, tipo: str) -> bool:
    if tipo.lower() == 'cpf':
        cpf = ''.join(c for c in dado if c.isdigit())
        if len(cpf) != 11:
            return False
        if cpf in [str(i)*11 for i in range(10)]:
            return False
        def calc_digito(digs):
            soma = sum(int(digs[i]) * (len(digs) + 1 - i) for i in range(len(digs)))
            resto = (soma * 10) % 11
            return 0 if resto == 10 else resto
        d1 = calc_digito(cpf[:9])
        d2 = calc_digito(cpf[:10])
        return d1 == int(cpf[9]) and d2 == int(cpf[10])
    elif tipo.lower() == 'cep':
        import re
        return bool(re.fullmatch(r'\d{5}-?\d{3}', dado))
    elif tipo.lower() == 'telefone':
        nums = ''.join(c for c in dado if c.isdigit())
        if len(nums) not in (10, 11):
            return False
        ddd = nums[:2]
        if not (11 <= int(ddd) <= 99):
            return False
        import re
        return bool(re.fullmatch(r'\(?\d{2}\)?[ ]?\d{4,5}-?\d{4}', dado))
    elif tipo.lower() == 'placa':
        import re
        placa = dado.upper()
        antigo = re.fullmatch(r'[A-Z]{3}-\d{4}', placa)
        novo = re.fullmatch(r'[A-Z]{3}\d[A-Z]\d{2}', placa)
        return antigo is not None or novo is not None
    else:
        return False

def parse_log_lines(log_text: str, nivel: str = '') -> list:
    if not log_text:
        return []
    linhas = log_text.strip().split('\n')
    resultado = []
    for linha in linhas:
        if not linha:
            continue
        if linha.startswith('['):
            fechamento = linha.find(']')
            if fechamento != -1:
                nivel_linha = linha[1:fechamento]
                mensagem = linha[fechamento+2:]
                if not nivel or nivel == nivel_linha:
                    resultado.append(mensagem)
    return resultado

def parse_ini_simple(ini_text: str) -> dict:
    if not ini_text:
        return {}
    linhas = ini_text.strip().split('\n')
    resultado = {}
    secao_atual = None
    for linha in linhas:
        linha = linha.strip()
        if not linha or linha.startswith('#'):
            continue
        if linha.startswith('[') and linha.endswith(']'):
            secao_atual = linha[1:-1]
            if secao_atual not in resultado:
                resultado[secao_atual] = {}
        elif '=' in linha and secao_atual:
            chave, valor = linha.split('=', 1)
            chave = chave.strip()
            valor = valor.strip()
            resultado[secao_atual][chave] = valor
    return resultado

def first_bad_version(n: int, is_bad: callable) -> int:
    esquerda, direita = 1, n
    while esquerda < direita:
        meio = (esquerda + direita) // 2
        if is_bad(meio):
            direita = meio
        else:
            esquerda = meio + 1
    return esquerda

def parse_log_level(log_text: str) -> dict[str, int]:
    contagem = {'INFO': 0, 'WARN': 0, 'ERROR': 0}
    if not log_text:
        return contagem
    for linha in log_text.split('\n'):
        linha = linha.strip()
        if linha.startswith('['):
            fechado = linha.find(']')
            if fechado > 1:
                nivel = linha[1:fechado]
                if nivel in contagem:
                    contagem[nivel] += 1
    return contagem
